    const d=Math.sqrt((sx2-sX)**2+(sy2-sY)**2);
    aS+=Math.sin(d*f-t*sp)*amp;
    iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5)*amp;
    dS+=Math.sin(d*f*1.5-t*sp*0.4+0.8)*amp*0.5;
