  const n=src.length,act=aS/n,inh=iS/n,diff=dS/n;
  const bg=(Math.sin(sx2*0.04+sy2*0.025+t*0.8)+Math.sin(sx2*0.03-sy2*0.04+t*1.1)+Math.sin(sx2*0.07+sy2*0.05-t*0.6)*0.5+Math.sin((sx2+sy2)*0.12+t*2.5)*0.2+Math.sin((sx2-sy2)*0.1-t*2)*0.2)/3.2;
