  const r1=Math.tanh((act-inh*0.7+bg*0.3+spiral)*2.2);
  const r2=Math.tanh((diff+act*0.5-inh*0.4+cell)*2.0);
  const coupled=Math.tanh(r1*0.7+r2*0.5+r1*r2*0.3);
  const micro=Math.sin(sx2*0.3+sy2*0.25+t*3)*Math.sin(sx2*0.2-sy2*0.3-t*2.5)*0.15;
  const blend=coupled*0.65+cell*0.2+micro*0.15,v=blend*0.5+0.5;
